import {mkdtempSync,readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
const dir=mkdtempSync(join(process.cwd(),'.git','b11-timeout-'));
writeFileSync(join(dir,'preload.ts'),'globalThis.__configLoaded = true;\n');
writeFileSync(join(dir,'timeout.test.ts'),'import {test,expect} from "bun:test";\ntest("configured timeout", async () => { expect(globalThis.__configLoaded).toBe(true); await Bun.sleep(200); });\n');
const cases=[{config:10,cli:[] as string[],expected:1},{config:1000,cli:[] as string[],expected:0},{config:1000,cli:['--timeout','10'],expected:1},{config:10,cli:['--timeout','1000'],expected:0}];
const runs=[];
for(const item of cases){
 writeFileSync(join(dir,'bunfig.toml'),'[test]\ncoverage = false\npreload = ["./preload.ts"]\ntimeout = '+item.config+'\n');
 const child=Bun.spawnSync([process.execPath,'test',...item.cli,'timeout.test.ts'],{cwd:dir,stdout:'pipe',stderr:'pipe',timeout:10000});
 const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
 runs.push({...item,exit:child.exitCode,output});
 console.log(JSON.stringify({...item,exit:child.exitCode}));
}
writeFileSync('.git/b11-timeout-'+process.platform+'.json',JSON.stringify({runtime:Bun.version,dir,runs,probeSource:readFileSync('.git/b11-timeout-probe.ts','utf8')},null,2)+'\n');

