import {readFileSync,writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {discoverInventory,sourceHash,validateInventory} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/', evidence=root+'evidence/';
const read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const save=(p:string,v:unknown)=>writeFileSync(p,JSON.stringify(v,null,2)+'\n');
const hash=(p:string)=>sourceHash(readFileSync(p,'utf8'));
const assert=(x:unknown,m:string)=>{if(!x)throw Error(m);};
const windows=read('.git/b11-timeout-win32.json'), linux=read('.git/b11-timeout-linux.json');
for(const packet of [windows,linux])assert(packet.runs.map((r:any)=>r.exit).join()==='0,0,1,0','Timeout comparison changed');
const red=readFileSync('.git/b11-timeout-package-red.txt','utf8');
assert(red.includes('5000ms')&&red.includes('1 fail'),'Missing RED');
const checks=[['Windows','.git/b11-timeout-package-green-windows.txt'],['Linux','.git/b11-timeout-package-green-linux.txt']].map(([platform,path])=>({platform,command:'bun run test ./.git/b11-timeout-package.test.ts',exit:0,output:readFileSync(path!,'utf8')}));
for(const check of checks)assert(check.output.includes('1 pass')&&check.output.includes('0 fail')&&check.output.includes('--timeout 15000'),'Missing GREEN invocation');
const catalog=discoverInventory(process.cwd()), manifest=read(root+'quality-classifications.json'), ledger=read(root+'work-items.json');
manifest.packages=catalog.packages;
assert(catalog.files.length===448&&validateInventory(catalog,manifest).length===0,'Invalid inventory');
save(root+'executable-catalog.json',catalog);save(root+'quality-classifications.json',manifest);
const linuxMetricsPath=evidence+'B11.1-driver-linux-metrics.json', combinedPath=evidence+'B11.1-driver-platform-metrics.json', packetPath=evidence+'B11.1-timeout-invocation.json';
const linuxMetrics=read('.git/b11-driver-current-linux.json');
for(const input of linuxMetrics.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale Linux metrics');
save(linuxMetricsPath,linuxMetrics);
const combined=read('.git/b11-driver-combined.json');
for(const input of combined.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale combined metrics');
assert(combined.files.at(-1).metrics.branches.covered===61&&combined.files.at(-1).metrics.branches.total===70,'Unexpected combined result');
save(combinedPath,{...combined,inputs:[evidence+'B11.1-driver-metrics.json',linuxMetricsPath].map(path=>({path,sourceHash:hash(path)})),files:combined.files.map(({rawCoverage,...file}:any)=>file)});
const item=ledger.items.find((x:any)=>x.id==='B11.1');
item.evidence=[...new Set([...item.evidence,packetPath,linuxMetricsPath,combinedPath])];
item.progress.timeout_resolution='Synthetic comparisons on Windows Bun 1.4.1/Linux Bun 1.3.14 prove TOML timeout ignored despite loaded preload; CLI timeout works. Actual package invocation fails a 5.25-second test before the change and passes it on both platforms after test script explicitly uses existing quality limit 15000 ms. Quality and smoke route through that entrypoint; direct bun test still needs its explicit flag.';
item.progress.remaining=[
 'Driver source and counter-map identical Windows/Linux diagnostics combine to 61/70 branches (87.14%); nine genuine failure/recovery outcomes remain. Both helpers have 100% on both runtimes. Address the nine outcomes listed in B11.1-driver-platform-metrics.json without deleting safety branches or adding exclusions.',
 'Eight killed mutations remain bounded decision proof. Final B05-B08 instrumenter, applicable driver metrics, source-bound review and full baseline acceptance remain open.'
];
save(root+'work-items.json',ledger);
const packageJson=read('package.json');
assert(packageJson.scripts.test==='bun test --timeout 15000'&&packageJson.scripts.quality.includes('&& bun run test &&')&&packageJson.scripts['test:smoke']==='bun run test tests/smoke','Dispatch changed');
save(packetPath,{item_id:'B11.1',status:'timeout invocation repaired; B11.1 remains active',recorded_at:new Date().toISOString(),base_revision:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),sourceInputs:['package.json','bunfig.toml','README.md'].map(path=>({path,sourceHash:hash(path)})),documentedBehaviorSource:'https://bun.sh/docs/test/configuration',observedBehavior:'Installed runtimes ignore test.timeout from TOML while reading preload; CLI timeout controls the same test. This is a runtime/documentation discrepancy, not proof of every Bun version.',syntheticComparisons:[windows,linux],regression:{source:readFileSync('.git/b11-timeout-package.test.ts','utf8'),red:{command:'bun run test ./.git/b11-timeout-package.test.ts',exit:1,output:red},green:checks},dispatch:{test:packageJson.scripts.test,quality:packageJson.scripts.quality,smoke:packageJson.scripts['test:smoke'],scope:'Underlying package invocation exercised on both platforms. Full quality/smoke suites were not executed or accepted; their existing prerequisites remain open.'},combinedMetrics:{artifact:combinedPath,sourceHash:hash(combinedPath),interpretation:'Map equality and source hashes checked before adding platform counters. Nine failure/recovery branch outcomes remain. No platform exclusion or final instrumenter approval.'},remaining:item.progress.remaining,recordingScript:readFileSync('.git/b11-timeout-record.ts','utf8')});
const edit=(p:string,fn:(s:string)=>string)=>writeFileSync(p,fn(readFileSync(p,'utf8')));
edit(root+'JOURNAL.md',s=>s.replace('# Memory resilience execution journal','# Memory resilience execution journal\n\n## 2026-09-20 - B11.1 timeout invocation repaired\n\n- Prior turn progressed at e449af9; resumed from a clean worktree.\n- Synthetic TOML/CLI comparisons prove both installed runtimes load preload but\n  ignore the TOML timeout. A 5.25-second package-invoked test fails before repair\n  at 5000 ms and passes on Windows/Linux with explicit 15000 ms. The package test\n  script now uses that existing quality limit; quality/smoke route through it.\n  Removed the misleading TOML setting and updated direct-invocation examples.\n- Reconciled unchanged-source Windows/Linux diagnostic maps. Helpers remain 100%;\n  driver branches combine to 61/70 (87.14%). Three former gaps were platform\n  choices; nine genuine failure/recovery outcomes remain, with exact locations\n  in B11.1-driver-platform-metrics.json. This is diagnostic, not final acceptance.\n- Current catalog package binding refreshed; 448 candidates/two packages.\n  B11.1 remains active; B04 review blocked and B05 pending. No full baseline,\n  installed product, model or replication acceptance is claimed.\n- Restart: exercise lock-holder startup failure and interrupted teardown, then\n  the remaining adversarial-fixture cleanup recovery outcomes. Preserve safety\n  branches; do not exempt the driver or change the Tier S requirement.\n'));
edit(root+'B11.1-plan.md',s=>s+'\nTimeout repair is verified through the package entrypoint on Windows and Linux.\nSee `evidence/B11.1-timeout-invocation.json`. Combined same-source driver counters\nnow identify nine remaining failure/recovery outcomes (61/70 branches). Continue\nwith lock-holder startup and interrupted teardown, then adversarial-fixture\nrecovery. The full quality and independent-review gates remain open.\n');
edit('.planning/STATE.md',s=>s.replace('driver branches remain 58/70 and default-timeout behavior needs disposition','combined Windows/Linux driver branches remain 61/70. TOML timeout behavior is reproduced and the package test entrypoint now explicitly uses the existing quality limit; a 5.25-second regression passes on both runtimes'));
edit('.git/memory-resilience-pr-body.md',s=>s.replace('while driver branches remain 58/70 (82.85%). Final driver applicability, default timeout behavior, complete Tier S and independent review remain open.','while combined Windows/Linux driver branches remain 61/70 (87.14%). A synthetic package-invoked timeout regression fails at 5000 ms before repair and passes on both runtimes after the test script explicitly uses the existing quality limit of 15000 ms. Quality/smoke route through that entrypoint; README examples use it. Final driver applicability, complete Tier S and independent review remain open.'));
console.log('Recorded timeout RED/GREEN and combined-platform remaining gaps; B11.1 active.');

