import {readFileSync,writeFileSync} from 'node:fs';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {sourceHash,discoverInventory,validateInventory} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/', read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const hash=(p:string)=>sourceHash(readFileSync(p,'utf8'));
const assert=(x:unknown,m:string)=>{if(!x)throw Error(m);};
const packetPath=root+'evidence/B11.1-timeout-invocation.json', packet=read(packetPath);
// The final README edit explicitly labels May baseline evidence as historical.
packet.sourceInputs.find((x:any)=>x.path==='README.md').sourceHash=hash('README.md');
for(const input of packet.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale input '+input.path);
const live=discoverInventory(process.cwd()), saved=read(root+'executable-catalog.json'), classifications=read(root+'quality-classifications.json');
assert(JSON.stringify(live)===JSON.stringify(saved)&&validateInventory(live,classifications).length===0,'Stale inventory');
const combined=read(packet.combinedMetrics.artifact);
assert(hash(packet.combinedMetrics.artifact)===packet.combinedMetrics.sourceHash,'Stale combined artifact');
for(const input of combined.inputs)assert(hash(input.path)===input.sourceHash,'Stale platform artifact');
const platforms=combined.inputs.map((x:any)=>read(x.path));
for(const input of combined.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale driver input');
for(const file of combined.files){
 const data=platforms.map((p:any)=>Object.values(p.rawCoverage).find((x:any)=>x.path.replaceAll('\\','/').endsWith('/'+file.path)) as any);
 for(const key of ['statementMap','fnMap','branchMap'])assert(JSON.stringify(data[0][key])===JSON.stringify(data[1][key]),'Mismatched counter maps');
 const map=createCoverageMap({});for(const counter of data)map.addFileCoverage({...counter,path:file.path});
 assert(JSON.stringify(map.fileCoverageFor(file.path).toSummary().data)===JSON.stringify(file.metrics),'Combined metric mismatch');
}
const ledger=read(root+'work-items.json'), ids=new Map<string,any>(ledger.items.map((x:any)=>[x.id,x])), visited=new Set<string>();
function visit(id:string,ancestors=new Set<string>()){assert(ids.has(id)&&!ancestors.has(id),'Invalid dependency');if(visited.has(id))return;for(const dep of ids.get(id).depends_on)visit(dep,new Set([...ancestors,id]));visited.add(id);}
assert(ids.size===218&&ids.size===ledger.items.length,'Ledger size');for(const id of ids.keys())visit(id);
assert(ids.get('B11.1').status==='active'&&ids.get('B04').status==='blocked'&&ids.get('B05').status==='pending','Premature acceptance');
packet.validation={command:'bun .git/b11-timeout-validate.ts',exit:0,source:readFileSync('.git/b11-timeout-validate.ts','utf8'),result:'Current package/config/docs hashes and 448-file/two-package inventory verified; unchanged-source platform counter maps and combined metrics reconciled; 218-item acyclic ledger retains open gates.',inventoryOutput:readFileSync('.git/b11-timeout-inventory.txt','utf8')};
writeFileSync(packetPath,JSON.stringify(packet,null,2)+'\n');console.log(packet.validation.result);
